#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    double *d = (double *)malloc(n * sizeof(double));
    double *r = (double *)malloc(n * sizeof(double));
    double *y = (double *)malloc(n * sizeof(double));
    if (!d || !r || !y) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%lf", &d[i]);
        r[i] = d[i] / 2.0;
    }

    /*
      Let the walls be horizontal, so we minimize the vertical distance H.
      Cylinder i has center at height y[i], radius r[i].

      For adjacent cylinders i-1 and i, if they touch each other, then:
        (x difference)^2 + (y[i]-y[i-1])^2 = (r[i]+r[i-1])^2
      Since x can be adjusted freely, the only necessary condition is:
        |y[i]-y[i-1]| <= r[i]+r[i-1]

      To minimize total height, each cylinder should be placed as low as possible:
        y[i] >= r[i]                          (touching bottom wall or above it)
        y[i] <= H - r[i]                      (below top wall)
        |y[i]-y[i-1]| <= r[i]+r[i-1]

      For a fixed H, greedily place:
        y[0] = r[0]
        y[i] = max(r[i], y[i-1] - (r[i-1]+r[i]))
      and also require y[i] <= y[i-1] + (r[i-1]+r[i]) and y[i] <= H-r[i].

      Simpler equivalent interval propagation:
      feasible interval for y[0] is [r[0], H-r[0]]
      then for each i:
        y[i] must lie in [r[i], H-r[i]]
        and within distance s from previous interval, s=r[i-1]+r[i]
      so new interval:
        [max(r[i], L-s), min(H-r[i], R+s)]
      If non-empty throughout, H is feasible.

      Binary search minimal feasible H.
    */

    double maxd = 0.0, sumd = 0.0;
    for (int i = 0; i < n; i++) {
        if (d[i] > maxd) maxd = d[i];
        sumd += d[i];
    }

    double lo = maxd, hi = sumd;
    for (int it = 0; it < 100; it++) {
        double H = (lo + hi) / 2.0;

        double L = r[0], R = H - r[0];
        int ok = (L <= R);

        for (int i = 1; i < n && ok; i++) {
            double s = r[i - 1] + r[i];
            double nL = L - s;
            double nR = R + s;

            if (nL < r[i]) nL = r[i];
            if (nR > H - r[i]) nR = H - r[i];

            if (nL > nR) ok = 0;
            else {
                L = nL;
                R = nR;
            }
        }

        if (ok) hi = H;
        else lo = H;
    }

    printf("%.10f\n", hi);

    free(d);
    free(r);
    free(y);
    return 0;
}

import java.util.Scanner;

public class CylindersBetweenWalls {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        double[] radii = new double[n];
        for (int i = 0; i < n; i++) {
            radii[i] = sc.nextDouble();
        }

        double totalWidth = radii[0] + radii[n - 1];
        for (int i = 0; i < n - 1; i++) {
            totalWidth += 2 * Math.sqrt(radii[i] * radii[i + 1]);
        }

        System.out.printf("%.3f%n", totalWidth);
    }
}

