#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n) {
        vector<double> d(n), r(n);
        for (int i = 0; i < n; ++i) {
            cin >> d[i];
            r[i] = d[i] / 2.0;
        }

        // y[i] = vertical position of center of cylinder i above the bottom wall
        // Minimal feasible y[i] is max of:
        // - touching bottom wall: r[i]
        // - touching any previous cylinder j:
        //   (x_i - x_j)^2 + (y_i - y_j)^2 = (r_i + r_j)^2
        //   with x_i - x_j = r_i + r_j  (adjacent in order, tangent along line)
        //   Actually cylinders may roll, but order fixed, so horizontal center distance
        //   between consecutive cylinders is r_i + r_{i+1}; hence between i and j it is
        //   sum of consecutive radii pairs = r[j] + 2*sum(mid) + r[i].
        // Easier: compute prefix sums of diameters, then x[i] = r[0] + sum_{k< i} (r[k]+r[k+1]).
        // This simplifies to x[i] = prefix_d[i] + r[i], where prefix_d[i] = sum_{k< i} d[k].
        vector<double> prefix(n + 1, 0.0);
        for (int i = 0; i < n; ++i) prefix[i + 1] = prefix[i] + d[i];

        vector<double> x(n), y(n);
        for (int i = 0; i < n; ++i) {
            x[i] = prefix[i] + r[i];
            y[i] = r[i];
            for (int j = 0; j < i; ++j) {
                double dx = x[i] - x[j];
                double sr = r[i] + r[j];
                if (dx <= sr + 1e-12) {
                    double val = sr * sr - dx * dx;
                    if (val < 0) val = 0;
                    y[i] = max(y[i], y[j] + sqrt(val));
                }
            }
        }

        double ans = 0.0;
        for (int i = 0; i < n; ++i) ans = max(ans, y[i] + r[i]);

        cout << fixed << setprecision(10) << ans << "\n";
    }

    return 0;
}
